import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"现代演进导读","description":"","frontmatter":{},"headers":[],"relativePath":"evolution/overview.md","filePath":"evolution/overview.md","lastUpdated":1791581342000}`),a={name:`evolution/overview.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="现代演进导读" tabindex="-1">现代演进导读 <a class="header-anchor" href="#现代演进导读" aria-label="Permalink to “现代演进导读”">​</a></h1><p>GoF 那本书定型于 1994 年 [S1]，它解决的是&quot;在继承体系里复用对象&quot;的问题。之后三十年里三件事把问题改了：语言不再以继承为中心（Go 根本没有继承，Java/C# 的默认选择也从继承变成接口与组合）、代码跑在多机与网络上（故障从&quot;写错&quot;变成&quot;下游不可达&quot;）、依赖由容器统一装配（对象不再自己 new 合作者）。本目录收 GoF 之后仍在演化、且工程上已经形成共识的七篇。</p><h2 id="本目录的七篇" tabindex="-1">本目录的七篇 <a class="header-anchor" href="#本目录的七篇" aria-label="Permalink to “本目录的七篇”">​</a></h2><ul><li><a href="/hello-design-patterns/evolution/composition-over-inheritance">组合式设计</a>：组合优先于继承的落地写法，Go、Vue、React 三个方向的证据。GoF 自己在书里就写了&quot;优先使用对象组合而非类继承&quot;，本篇讲它在语言层面怎么兑现。</li><li><a href="/hello-design-patterns/evolution/solid">SOLID 与依赖规则</a>：五条原则与依赖方向。来源是 Martin 2002 与 2017 两本书 [S3][S4]，Head First 第 2 版把它带进入门读物 [S2]。</li><li><a href="/hello-design-patterns/evolution/circuit-breaker">熔断器</a>：跨进程调用失败率超阈值就短路，来自 Release It! [S12]。GoF 的代理与装饰控制的是进程内访问，熔断控制的是网络边界。</li><li><a href="/hello-design-patterns/evolution/bulkhead">隔舱</a>：资源按下游分池，一个下游变慢只吃光自己那一格，来自 Release It! [S12]。</li><li><a href="/hello-design-patterns/evolution/timeout">超时</a>：每次跨进程调用都带截止时间，&quot;慢&quot;先转成&quot;失败&quot;，来自 Release It! [S12]。</li><li><a href="/hello-design-patterns/evolution/retry">重试</a>：瞬时故障按指数退避加抖动重试，前提是幂等，来自 Release It! [S12]。</li><li><a href="/hello-design-patterns/anti-patterns/overview">反模式目录</a> 不在本目录，但它与本目录互为正反面，选题时一起看。</li></ul><h2 id="与已有分区的关系" tabindex="-1">与已有分区的关系 <a class="header-anchor" href="#与已有分区的关系" aria-label="Permalink to “与已有分区的关系”">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>旧分区的做法</th><th>本目录补的</th></tr></thead><tbody><tr><td>复用与扩展</td><td><a href="/hello-design-patterns/behavioral/template-method">继承</a>、<a href="/hello-design-patterns/structural/bridge">桥接</a>、<a href="/hello-design-patterns/structural/decorator">装饰</a> 都能解</td><td>什么时候不该用继承，怎么用组合写等价代码</td></tr><tr><td>依赖方向</td><td><a href="/hello-design-patterns/structural/dependency-injection">依赖注入</a>、<a href="/hello-design-patterns/creational/service-locator">服务定位器</a> 各讲一半</td><td>五条原则把&quot;谁该依赖谁&quot;定下来</td></tr><tr><td>调用失败</td><td><a href="/hello-design-patterns/structural/proxy">代理</a>、<a href="/hello-design-patterns/behavioral/chain-of-responsibility">责任链</a> 处理进程内失败</td><td>网络失败需要时间窗、阈值、半开状态，进程内模式没有这些</td></tr></tbody></table><h2 id="选题口径" tabindex="-1">选题口径 <a class="header-anchor" href="#选题口径" aria-label="Permalink to “选题口径”">​</a></h2><p>进这个目录要满足三条，缺一条记入<a href="/hello-design-patterns/research/coverage">差异表</a>的&quot;暂不收录&quot;：</p><ol><li>有出处：出自书籍或官方文档，不是社区口口相传（对应来源清单 [S1]–[S28]）。</li><li>有共识：至少两个主流语言或框架有标准实现。</li><li>与 GoF 条目互补而不是换名：换名的写进对应模式篇的别名段，不单开一篇。</li></ol><p>隔舱、超时、重试（同出 Release It! [S12]）已按这个口径补齐；仓储与单元工作（同出 PoEAA [S5]、DDD [S11]）已按「领域层接口」口径补齐，见<a href="/hello-design-patterns/other/repository">仓储与单元工作</a>。规格属战略设计词汇，不在「模式」口径内；架构风格类（分层、管道-过滤器）按判据维持不收录，处置见<a href="/hello-design-patterns/research/coverage">差异表</a>。</p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to “怎么读”">​</a></h2><p>先读<a href="/hello-design-patterns/evolution/composition-over-inheritance">组合式设计</a>，它是后面各篇的共同底座；<a href="/hello-design-patterns/evolution/solid">SOLID 与依赖规则</a>决定依赖怎么摆；跨进程的四篇连着读：<a href="/hello-design-patterns/evolution/bulkhead">隔舱</a>先分仓，<a href="/hello-design-patterns/evolution/timeout">超时</a>给每次调用限时，<a href="/hello-design-patterns/evolution/retry">重试</a>恢复瞬时故障，<a href="/hello-design-patterns/evolution/circuit-breaker">熔断器</a>在故障持续时断闸。</p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};